private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    if (i >= bb.remaining()) {
        return i;
    }

    int byte1 = bb.get(i) & 0xFF;

    int codePoint;
    int nextIndex;

    if ((byte1 & 0x80) == 0) {
        // 1-byte ASCII
        // 0xxxxxxx
        codePoint = byte1;
        nextIndex = i + 1;
    } else if ((byte1 & 0xE0) == 0xC0) {
        // 2-byte sequence
        // 110xxxxx 10xxxxxx
        if (i + 1 >= bb.remaining()) {
            throw new IllegalArgumentException("Incomplete UTF-8 sequence at index " + i);
        }
        int byte2 = bb.get(i + 1) & 0xFF;
        if ((byte2 & 0xC0) != 0x80) {
            throw new IllegalArgumentException("Invalid UTF-8 continuation byte at index " + (i + 1));
        }
        codePoint = ((byte1 & 0x1F) << 6) | (byte2 & 0x3F);
        nextIndex = i + 2;
    } else if ((byte1 & 0xF0) == 0xE0) {
        // 3-byte sequence
        // 1110xxxx 10xxxxxx 10xxxxxx
        if (i + 2 >= bb.remaining()) {
            throw new IllegalArgumentException("Incomplete UTF-8 sequence at index " + i);
        }
        int byte2 = bb.get(i + 1) & 0xFF;
        int byte3 = bb.get(i + 2) & 0xFF;
        if ((byte2 & 0xC0) != 0x80 || (byte3 & 0xC0) != 0x80) {
            throw new IllegalArgumentException("Invalid UTF-8 continuation byte");
        }
        codePoint = ((byte1 & 0x0F) << 12) | ((byte2 & 0x3F) << 6) | (byte3 & 0x3F);
        nextIndex = i + 3;
    } else if ((byte1 & 0xF8) == 0xF0) {
        // 4-byte sequence
        // 11110xxx 10xxxxxx 10xxxxxx 10xxxxxx
        if (i + 3 >= bb.remaining()) {
            throw new IllegalArgumentException("Incomplete UTF-8 sequence at index " + i);
        }
        int byte2 = bb.get(i + 1) & 0xFF;
        int byte3 = bb.get(i + 2) & 0xFF;
        int byte4 = bb.get(i + 3) & 0xFF;
        if ((byte2 & 0xC0) != 0x80 || (byte3 & 0xC0) != 0x80 || (byte4 & 0xC0) != 0x80) {
            throw new IllegalArgumentException("Invalid UTF-8 continuation byte");
        }
        codePoint = ((byte1 & 0x07) << 18) | ((byte2 & 0x3F) << 12) | ((byte3 & 0x3F) << 6) | (byte4 & 0x3F);
        nextIndex = i + 4;
    } else {
        throw new IllegalArgumentException("Invalid UTF-8 start byte at index " + i);
    }

    sb.appendCodePoint(codePoint);
    return nextIndex;
}
