private void enlarge(final int size) {
    if (size < 0) {
        throw new IllegalArgumentException("Size to enlarge must be non-negative, but was: " + size);
    }
    if (size == 0) {
        return;
    }
    int newSize = this.size() + size;
    if (newSize < 0) {
        throw new IllegalArgumentException("New size would exceed maximum array size");
    }
    byte[] newBuffer = new byte[newSize];
    System.arraycopy(this.data, 0, newBuffer, 0, this.size());
    this.data = newBuffer;
}
