public static int nullSafeHashCode(long[] array){
    if (array == null) {
        return 0;
    }
    int hashCode = 1;
    for (long element : array) {
        int elementHashCode = (int)(element ^ (element >>> 32));
        hashCode = 31 * hashCode + elementHashCode;
    }
    return hashCode;
}
