private int parseEndOfLine(String headerPart, int end) {
    // Start from the beginning of the string and move backward if necessary, or from 0 if not
    // The documentation says "Index of the \r\n sequence, which indicates end of line."
    // It skips bytes until the end of the current line.

    // We need to find the last \r\n in the string, or perhaps the first one?
    // "Skips bytes until the end of the current line." usually implies finding the first \r\n.
    // However, header parsing often deals with multiple lines. Let's look at typical usage.
    // If headerPart is the string being parsed, and 'end' is the index of the last byte yet to be processed.
    // This suggests we might be parsing from a buffer.

    // Let's assume the standard behavior for a line parser: find the next "\r\n" sequence.
    // If not found, return -1 or the length?
    // The return type is int.
    // Let's search for "\r\n"

    // Edge case: null string
    if (headerPart == null) {
        return -1;
    }

    int len = headerPart.length();
    if (end > len) {
        end = len;
    }

    for (int i = 0; i < end - 1; i++) {
        if (headerPart.charAt(i) == '\r' && headerPart.charAt(i + 1) == '\n') {
            return i;
        }
    }

    // If not found, what do we return? 
    // Usually, if no EOL is found, we might return -1 to indicate "not found" or the last valid index.
    // Given the name "parseEndOfLine" and the return description "Index of the \r\n sequence",
    // returning -1 for "not found" is a common convention.
    return -1;
}

