@Override
public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // Get the parameter values for the two partitions
    int paramSize1 = getParameter("size1");
    int paramSize2 = getParameter("size2");

    if (paramSize1 < 0 || paramSize2 < 0) {
        throw new IllegalArgumentException("Partition sizes must be non-negative");
    }

    List<V> partition1 = new ArrayList<>();
    List<V> partition2 = new ArrayList<>();

    // Create vertices for partition 1 and store in resultMap
    for (int i = 0; i < paramSize1; i++) {
        V vertex = createVertex();
        String key = "partition1_" + i;
        resultMap.put(key, vertex);
        target.addVertex(vertex);
        partition1.add(vertex);
    }

    // Create vertices for partition 2 and store in resultMap
    for (i = 0; i < paramSize2; i++) {
        V vertex = createVertex();
        String key = "partition2_" + i;
        resultMap.put(key, vertex);
        target.addVertex(vertex);
        partition2.add(vertex);
    }

    // Connect every vertex in partition1 to every vertex in partition2
    for (V v1 : partition1) {
        for (V v2 : partition2) {
            target.addEdge(v1, v2, createEdge(v1, v2));
        }
    }
}
