protected void subAppend(LoggingEvent event) {
    try {
        if (event == null) {
            throw new IllegalArgumentException("LoggingEvent cannot be null");
        }

        // Format the logging event
        String message = formatMessage(event);
        String level = event.getLevel().toString();
        long timestamp = event.getTimeStamp();
        String threadName = event.getThreadName();
        String loggerName = event.getLoggerName();
        String exception = event.getThrowableStrRep();

        // Construct the log line
        StringBuilder sb = new StringBuilder();
        sb.append(timestamp);
        sb.append(" ");
        sb.append(level);
        sb.append(" ");
        sb.append(loggerName);
        sb.append(" - ");
        sb.append(message);
        if (exception != null) {
            sb.append("\n").append(exception);
        }
        sb.append("\n");

        // Write the formatted message to the output stream
        synchronized (this) {
            out.write(sb.toString());
            out.flush();
        }
    } catch (Exception e) {
        handleError("Failed to append event: " + event, e, LoggingEvent.ERROR_ID);
    }
}

