public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType == null || targetType == null) {
        return null;
    }
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType parameterizedType = (ParameterizedType) genericType;
    Type[] typeArguments = parameterizedType.getActualTypeArguments();
    if (typeArguments == null || typeArguments.length == 0) {
        return null;
    }
    Class<?>[] args = new Class<?>[typeArguments.length];
    for (int i = 0; i < typeArguments.length; i++) {
        if (!(typeArguments[i] instanceof Class)) {
            return null;
        }
        Class<?> typeArg = (Class<?>) typeArguments[i];
        if (typeArg.isPrimitive()) {
            if (typeArg == int.class) args[i] = Integer.class;
            else if (typeArg == long.class) args[i] = Long.class;
            else if (typeArg == double.class) args[i] = Double.class;
            else if (typeArg == float.class) args[i] = Float.class;
            else if (typeArg == boolean.class) args[i] = Boolean.class;
            else if (typeArg == byte.class) args[i] = Byte.class;
            else if (typeArg == short.class) args[i] = Short.class;
            else if (typeArg == char.class) args[i] = Character.class;
            else return null;
        } else {
            args[i] = typeArg;
        }
    }
    return args;
}

