public Mappings diffStructure(String tableName, Mappings mappings) {
    if (tableName == null || tableName.isEmpty()) {
        throw new IllegalArgumentException("Table name cannot be null or empty");
    }
    if (mappings == null) {
        throw new IllegalArgumentException("Mappings cannot be null");
    }

    Mappings currentMappings = getCurrentMappings(tableName);
    if (currentMappings == null) {
        return new Mappings();
    }

    Mappings diff = new Mappings();
    Map<String, Object> mapField = currentMappings.get("properties");
    if (mapField == null) {
        mapField = currentMappings.get("fields");
    }

    Map<String, Object> mapHistory = mappings.get("properties");
    if (mapHistory == null) {
        mapHistory = mappings.get("fields");
    }

    if (mapField == null || mapField.isEmpty()) {
        return diff;
    }

    if (mapHistory == null || mapHistory.isEmpty()) {
        diff.putAll(mapField);
        return diff;
    }

    for (Map.Entry<String, Object> entry : mapField.entrySet()) {
        String key = entry.getKey();
        if (!mapHistory.containsKey(key)) {
            diff.put(key, entry.getValue());
        }
    }

    return diff;
}

