static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        return timeBucket;
    }

    // Extract year, month, day from the time bucket
    long year = timeBucket / 10000;
    long month = (timeBucket % 10000) / 100;
    long day = timeBucket % 100;

    if (month < 1 || month > 12 || day < 1) {
        return timeBucket;
    }

    // Determine the number of days in the month
    int[] daysInMonth = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    if (month == 2) {
        // Check for leap year
        if ((year % 4 == 0 && year % 100 != 0) || (year % 400 == 0)) {
            daysInMonth[1] = 29;
        } else {
            daysInMonth[1] = 28;
        }
    }

    if (day > daysInMonth[(int)month - 1]) {
        return timeBucket;
    }

    // The start of the month is day 1
    // The bucket start day is: 1 + ((day - 1) / dayStep) * dayStep
    // But we also need to clamp to the last valid day of the month
    long bucketStartDay = 1 + ((day - 1) / dayStep) * dayStep;
    long monthLastDay = daysInMonth[(int)month - 1];

    // If the bucket start day exceeds the last day of the month, use the last day of the month
    if (bucketStartDay > monthLastDay) {
        bucketStartDay = monthLastDay;
    }

    // Construct the compressed time bucket
    return year * 10000 + month * 100 + bucketStartDay;
}
