public static String findAndSubst(String key, Properties props) {
    if (key == null || props == null) {
        return "";
    }

    String rawValue = (String) props.get(key);
    if (rawValue == null) {
        return "";
    }

    String result = rawValue;
    java.util.regex.Pattern pattern = java.util.regex.Pattern.compile("\\$\\{(\\w+)\\}");
    java.util.regex.Matcher matcher = pattern.matcher(result);
    StringBuffer sb = new StringBuffer();

    while (matcher.find()) {
        String replacementKey = matcher.group(1);
        String replacementValue = (String) props.get(replacementKey);
        if (replacementValue == null) {
            replacementValue = "${" + replacementKey + "}";
        }
        matcher.appendReplacement(sb, java.util.regex.Matcher.quoteReplacement(replacementValue));
    }
    matcher.appendTail(sb);

    return sb.toString();
}
