        for (String segment : segments) {
            if (segment.length() > 0) {
                pathSegments.add(segment);
            }
        }
        List<PathSegmentImpl> result = new ArrayList<PathSegmentImpl>();
        for (String segment : pathSegments) {
            if (decode) {
                segment = decodePathSegment(segment);
            }
            result.add(new PathSegmentImpl(segment));
        }
