public void valueAccumulation(String key, Long value) {
    if (key == null || value == null) {
        throw new IllegalArgumentException("Key and value must not be null");
    }

    Long existingValue = accumulatedValues.get(key);
    if (existingValue == null) {
        accumulatedValues.put(key, value);
    } else {
        long newValue = existingValue + value;
        long max = Long.MAX_VALUE;
        long min = Long.MIN_VALUE;
        if (value > 0 && existingValue > max - value) {
            newValue = max; // Overflow
        } else if (value < 0 && existingValue < min - value) {
            newValue = min; // Underflow
        } else {
            newValue = existingValue + value;
        }
        accumulatedValues.put(key, newValue);
    }
}
