public static String capitalize(String name){
    if (name == null || name.length() == 0) {
        return name;
    }
    char c = name.charAt(0);
    String rest = name.substring(1);
    if (rest.length() == 0) {
        return Character.toUpperCase(c) + "";
    }
    if (rest.length() > 1 && rest.charAt(0) >= 'a' && rest.charAt(0) <= 'z' && rest.charAt(1) >= 'a' && rest.charAt(1) <= 'z') {
        // two or more lowercase letters following, so capitalize only first letter
        return Character.toUpperCase(c) + rest;
    } else if (rest.length() > 0 && Character.isUpperCase(rest.charAt(0))) {
        // next letter is uppercase, so just keep original
        return name;
    }
    // default: capitalize first letter
    return Character.toUpperCase(c) + name.substring(1);
}
