public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    if (node == null) {
        return 0;
    }

    int count = 0;
    while (node != null) {
        byte[] buffer = node.buffer.array();
        int length = Math.min(node.length, node.limit - node.position);
        if (node.position > 0 && node.position + length < buffer.length) {
            // We need to copy the relevant portion out
            byte[] copy = new byte[length];
            System.arraycopy(buffer, node.position, copy, 0, length);
            out.write(copy);
        } else if (node.position < buffer.length) {
            // Write the relevent part directly
            int bytesToWrite = Math.min(length, buffer.length - node.position);
            out.write(buffer, node.position, bytesToWrite);
            length -= bytesToWrite;
            node.position += bytesToWrite;
            // if more data, continue with next buffer
            if (length > 0 && node.next != null) {
                node = node.next;
                length = node.length;
                // reset position for the next node
                node.position = 0;
            }
        }
        count += node.length;
        node = node.next;
    }
    return count;
}
