private void putAbstractTypes(final int start, final int end) {
    int index = start;
    for (int i = start; i < end; ++i) {
        int type = currentFrame[i];
        if (type == Item.NULL) {
            stackMapTableEntries.put8((byte) 0);
        } else if (type == Item.BOOLEAN || type == Item.CHAR
                || type == Item.BYTE || type == Item.SHORT) {
            stackMapTableEntries.put8((byte) 1);
            stackMapTableEntries.putUTF8("I");
        } else if (type == Item.INT) {
            stackMapTableEntries.put8((byte) 1); // ITEM_Integer
            stackMapTableEntries.putUTF8("I");
        } else if (type == Item.FLOAT) {
            stackMapTableEntries.put8((byte) 1); // ITEM_Float
            stackMapTableEntries.putUTF8("F");
        } else if (type == Item.LONG) {
            stackMapTableEntries.put8((byte) 1); // ITEM_Long
            stackMapTableEntries.putUTF8("J");
            // Check if the next slot is also part of the long
            if (i + 1 < end && currentFrame[i + 1] == -1) {
                // Already handled above, reporting currentFrame[i]
            }
        } else if (type == Item.DOUBLE) {
            stackMapTableEntries.put8((byte) 1); // ITEM_Double
            stackMapTableEntries.putUTF8("D");
        } else if (type == MethodVisitor.ITEM_TOP) {
            // Item.TOP and null are treated as nothing.
        } else if (type > 0) {
            // Object type
            stackMapTableEntries.put8((byte) 7); // ITEM_Class
            stackMapTableEntries.put12(type);
            // Object types occupy one slot, so no need to skip ahead
        } else {
            // Return address type
            stackMapTableEntries.put8((byte) 8);
            stackMapTableEntries.put12(type);
        }
    }
