private Map<String,Object> buildContent(JsonObject jsonObject){
    Map<String, Object> content = new HashMap<>();
    if (jsonObject != null) {
        for (Map.Entry<String, JsonElement> entry : jsonObject.entrySet()) {
            String key = entry.getKey();
            JsonElement value = entry.getValue();
            if (value.isJsonPrimitive()) {
                PrimitiveType primitiveType = value.getAsJsonPrimitive().getType();
                if (primitiveType == PrimitiveType.STRING) {
                    content.put(key, value.getAsString());
                } else if (primitiveType == PrimitiveType.NUMBER) {
                    content.put(key, value.getAsNumber());
                } else if (primitiveType == PrimitiveType.BOOLEAN) {
                    content.put(key, value.getAsBoolean());
                }
            } else if (value.isJsonNull()) {
                content.put(key, null);
            } else {
                // Handle non-primitive types, maybe convert to string or ignore
                content.put(key, value.toString());
            }
        }
    }
    return content;
}

