public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    int len = str.length();
    if (len == 0) {
        return str;
    }
    StringBuilder buf = new StringBuilder(len);
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (i + 1 >= len) {
                buf.append(c);
                break;
            }
            i++;
            char next = str.charAt(i);
            switch (next) {
                case 'b':
                    buf.append('\b');
                    break;
                case 't':
                    buf.append('\t');
                    break;
                case 'n':
                    buf.append('\n');
                    break;
                case 'f':
                    buf.append('\f');
                    break;
                case 'r':
                    buf.append('\r');
                    break;
                case 'u':
                    if (i + 4 < len) {
                        String hex = str.substring(i + 1, i + 5);
                        try {
                            int value = Integer.parseInt(hex, 16);
                            buf.append((char) value);
                            i += 4;
                        } catch (NumberFormatException e) {
                            throw new IllegalArgumentException("Invalid Unicode escape sequence: \\u" + hex, e);
                        }
                    } else {
                        throw new IllegalArgumentException("Invalid Unicode escape sequence: incomplete");
                    }
                    break;
                case '\\':
                    buf.append('\\');
                    break;
                case '\'':
                    buf.append('\'');
                    break;
                case '"':
                    buf.append('"');
                    break;
                default:
                    buf.append('\\').append(next);
                    break;
            }
        } else {
            buf.append(c);
        }
    }
    return buf.toString();
}
