final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    final int tag = classFileBuffer.getByte(constantPoolEntryIndex + 1) & 0xFF;
    if (tag != CONSTANT_Utf8) {
        return null;
    }

    final int byteLength = classFileBuffer.getInt(constantPoolEntryIndex + 2) & 0xFFFFFFFF;
    int offset = constantPoolEntryIndex + 4;
    int charIndex = 0;

    while (offset < constantPoolEntryIndex + 2 + byteLength) {
        int codePoint = classFileBuffer.getByte(offset) & 0xFF;

        if (codePoint == 0) {
            break;
        }

        if (codePoint < 0x80) {
            // Single byte
            charBuffer[charIndex++] = (char) codePoint;
            offset += 1;
        } else if (codePoint < 0xC0) {
            // Unexpected continuation byte
            charBuffer[charIndex++] = 0xFFFD;
            offset += 1;
        } else if (codePoint < 0xE0) {
            // Two bytes
            int nextByte = classFileBuffer.getByte(offset + 1) & 0xFF;
            codePoint = ((codePoint & 0x1F) << 6) | (nextByte & 0x3F);
            charBuffer[charIndex++] = (char) codePoint;
            offset += 2;
        } else if (codePoint < 0xF0) {
            // Three bytes
            int byte1 = classFileBuffer.getByte(offset + 1) & 0xFF;
            int byte2 = classFileBuffer.getByte(offset + 2) & 0xFF;
            codePoint = ((codePoint & 0x0F) << 12) | ((byte1 & 0x3F) << 6) | (byte2 & 0x3F);
            if (codePoint >= 0x10000) {
                codePoint -= 0x10000;
                charBuffer[charIndex++] = (char) (0xD800 + (codePoint >> 10));
                charBuffer[charIndex++] = (char) (0xDC00 + (codePoint & 0x3FF));
            } else {
                charBuffer[charIndex++] = (char) codePoint;
            }
            offset += 3;
        } else {
            // Four or more bytes - treat as invalid
            charBuffer[charIndex++] = 0xFFFD;
            int count = 1;
            if (codePoint >= 0xF0) {
                count = 4;
            } else if (codePoint >= 0xF8) {
                count = 5;
            } else if (codePoint >= 0xFC) {
                count = 6;
            }
            offset += count;
        }
    }

    return new String(charBuffer, 0, charIndex);
}
