private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);
    do {
        Node node = circ.node();
        if (predicate.test(node)) {
            return circ;
        }
        if (node == stop) {
            break;
        }
        // Advance the circulator in the specified direction
        if (dir == 1) {
            circ = new OuterFaceCirculator(circ.onNode(), 1);
        } else if (dir == -1) {
            circ = new OuterFaceCirculator(circ.offNode(), -1);
        } else {
            throw new IllegalArgumentException("Invalid direction: " + dir);
        }
    } while (circ.node() != start);
    return circ;
}

