/**
 * Checks whether the sharding key indices for the given model are continuous.
 *
 * @param modelName the name of the model to check
 * @throws IllegalStateException if the sharding key indices are not continuous
 */
private void check(String modelName) throws IllegalStateException {
    if (modelName == null || modelName.isEmpty()) {
        return;
    }

    // Assume EntityMeta and ShardingKeyInfo classes exist in the project scope.
    // shardingKeyMapper is an assumed injected or accessible map.
    Map<String, Object> meta = this.entityMetaMapper.selectByKeyOnName(modelName);
    if (meta == null) {
        return;
    }

    List<Map<String, Object>> shardingKeyIndices = (List<Map<String, Object>>) meta.get("shardingKeyIndices");

    if (shardingKeyIndices == null || shardingKeyIndices.isEmpty() || shardingKeyIndices.size() == 1) {
        return;
    }

    for (int i = 0; i < shardingKeyIndices.size() - 1; i++) {
        Integer indexI = (Integer) shardingKeyIndices.get(i).get("index");
        Integer indexIPlus1 = (Integer) shardingKeyIndices.get(i + 1).get("index");

        if (indexI == null || indexIPlus1 == null || indexI + 1 != indexIPlus1) {
            throw new IllegalStateException("Sharding key indices must be continuous for model: " + modelName);
        }
    }
}
