protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || tour.isEmpty()) {
        return new GraphWalk<>(graph, graph.getVertices(), false);
    }

    // Find a starting vertex that has an incident edge in the tour
    V startVertex = null;
    for (E edge : tour) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);
        if (source != null) {
            startVertex = source;
            break;
        }
    }

    if (startVertex == null) {
        return new GraphWalk<>(graph, graph.getVertices(), false);
    }

    // Build the path by following edges
    List<V> vertices = new ArrayList<>();
    List<E> edges = new ArrayList<>();
    vertices.add(startVertex);
    Set<E> usedEdges = new HashSet<>(tour);
    Set<V> visitedVertices = new HashSet<>();
    visitedVertices.add(startVertex);

    V currentVertex = startVertex;
    while (!usedEdges.isEmpty()) {
        // Find an unused edge incident to currentVertex
        E nextEdge = null;
        for (E edge : graph.getEdgesIncidentTo(currentVertex)) {
            if (usedEdges.contains(edge)) {
                nextEdge = edge;
                break;
            }
        }

        if (nextEdge == null) {
            break;
        }

        usedEdges.remove(nextEdge);
        edges.add(nextEdge);

        // Determine the next vertex
        V otherVertex;
        if (graph.getEdgeSource(nextEdge).equals(currentVertex)) {
            otherVertex = graph.getEdgeTarget(nextEdge);
        } else if (graph.getEdgeTarget(nextEdge).equals(currentVertex)) {
            otherVertex = graph.getEdgeSource(nextEdge);
        } else {
            break;
        }

        vertices.add(otherVertex);
        visitedVertices.add(otherVertex);
        currentVertex = otherVertex;
    }

    return new GraphWalk<>(graph, vertices, edges);
}
