    // Check if a similar item already exists in the constant pool
    for (int i = 0; i < constants.size(); i++) {
        if (constants.get(i) instanceof Symbol) {
            Symbol sym = (Symbol) constants.get(i);
            if (sym.tag == CONSTANT_NameAndType && name.equals(sym.name) && descriptor.equals(sym.descriptor)) {
                return i;
            }
        }
    }

    // Add the new CONSTANT_NameAndType_info item
