    private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
        if (minLabel < 0 || minLabel >= bucketsByLabel.size()) {
            throw new IllegalArgumentException("minLabel is out of bounds");
        }
        Set<Integer> sourceBucket = bucketsByLabel.get(minLabel);
        if (sourceBucket == null) {
            return;
        }

        Set<Integer> destinationBucket = bucketsByLabel.get(0);
        if (destinationBucket == null) {
            destinationBucket = new HashSet<>();
            bucketsByLabel.set(0, destinationBucket);
        }

        for (Integer vertex : sourceBucket) {
            if (vertex < 0 || vertex >= labels.size()) {
                continue;
            }
            // Move the vertex to the bucket with label 0
            if (labels.get(vertex) == minLabel) {
                labels.set(vertex, 0);
                destinationBucket.add(vertex);
            }
        }

        // Clear the source bucket
        sourceBucket.clear();
    }
