private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    if (bounds == null) {
        return Pair.of(Collections.emptyList(), 0L);
    }
    int n = bounds.size();
    List<Integer> suffixSum = new ArrayList<>(n);
    long totalSum = 0L;
    for (int i = 0; i < n; i++) {
        if (bounds.get(i) == null) {
            return Pair.of(Collections.emptyList(), 0L);
        }
        totalSum += bounds.get(i);
    }
    long runningSum = totalSum;
    for (int i = n - 1; i >= 0; i--) {
        suffixSum.add(runningSum);
        runningSum -= bounds.get(i);
    }
    Collections.reverse(suffixSum);
    return Pair.of(suffixSum, totalSum);
}

