public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null) {
        return;
    }

    // Swap from and to if from > to
    if (from > to) {
        int temp = from;
        from = to;
        to = temp;
    }

    int length = arr.length;
    from = Math.max(from, 0);
    to = Math.min(to, length - 1);

    if (from >= to) {
        return;
    }

    while (from < to) {
        V temp = arr[from];
        arr[from] = arr[to];
        arr[to] = temp;
        from++;
        to--;
    }
}
