        } else if (viewRect.y + viewRect.height > scrollY + scrollHeight) {
            // Row is below the current view
            pane.getVerticalScrollBar().setValue(viewRect.y + viewRect.height - scrollHeight);
        }

        // Delayed repaint to ensure the selection is painted correctly
        table.repaint();
        table.revalidate();

        // A more robust way to handle rendering off-screen rows is to use a Timer or invokeAndWait
        // However, the prompt specifically mentions "delayed long enough" and "repaint()".
        // Sometimes just calling repaint/revalidate isn't enough if the component hasn't laid out yet.

        // A common pattern for ensuring UI updates are flushed is to use a Timer to trigger a final repaint after layout is complete.
        javax.swing.SwingUtilities.invokeLater(() -> {
            table.repaint();
        });
