public void abbreviate(final int nameStart, final StringBuffer buf) {
    if (nameStart < 0 || nameStart >= this.words.size()) {
        buf.append("...");
        return;
    }

    int lastWordEnd = this.words.size() - 2;
    if (lastWordEnd < nameStart) {
        lastWordEnd = nameStart;
    }

    // Append the first word
    buf.append(this.words.get(nameStart));

    // Append a space
    buf.append(' ');

    // Append the middle words abbreviated
    if (nameStart < lastWordEnd) {
        buf.append('\'');
    } else {
        buf.append("...");
    }
}
