private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    if (vertices == null || vertices.isEmpty()) {
        return true;
    }
    for (V v : vertices) {
        if (!graph.containsVertex(v)) {
            return false;
        }
        for (V u : vertices) {
            if (v.equals(u)) {
                continue;
            }
            if (!graph.containsEdge(v, u)) {
                return false;
            }
        }
    }
    return true;
