    private void pop(final String descriptor) {
        // Determine the number of abstract types to pop based on the descriptor
        // If the descriptor is null or empty, nothing to pop
        if (descriptor == null || descriptor.isEmpty()) {
            return;
        }

        // The descriptor is either a method descriptor (starts with '(') or a single type.
        // For a method descriptor, we need to pop the argument types.
        if (descriptor.charAt(0) == '(') {
            // Parse the argument types from the method descriptor
            int start = 1; // skip '('
            int end = descriptor.indexOf(')');
            if (end == -1) {
                throw new IllegalArgumentException("Invalid method descriptor: " + descriptor);
            }
            String args = descriptor.substring(start, end);
            int index = 0;
            while (index < args.length()) {
                if (args.charAt(index) == 'L') {
                    // Object type
                    popType(args.substring(index));
                    int semicolonIndex = args.indexOf(';', index);
                    if (semicolonIndex == -1) {
                        throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
                    }
                    index = semicolonIndex + 1;
                } else if (args.charAt(index) == '[') {
                    // Array type, skip the first '[' and process the remainder
                    popType(args.substring(index));
                    index++;
                } else {
                    // Primitive type
                    popType(args.substring(index, index + 1));
                    index++;
                }
            }
        } else {
            // Single type descriptor
            popType(descriptor);
        }
    }
