private List<Integer> computeUpperBounds(List<K> keys) {
    if (keys == null || keys.isEmpty()) {
        return new ArrayList<>();
    }
    // Track the minimum lower bound (upper bound) for each key
    List<Integer> upperBounds = new ArrayList<>(Collections.nCopies(keys.size(), Integer.MAX_VALUE));
    // For each key, iterate through all subsequent keys to find the minimum value that is strictly greater than the current key
    Map<K, Integer> keyToMinUpper = new HashMap<>();
    for (int i = 0; i < keys.size(); i++) {
        K currentKey = keys.get(i);
        int minUpper = Integer.MAX_VALUE;
        for (int j = i + 1; j < keys.size(); j++) {
            int value = toIntegerValue(keys.get(j));
            if (value > toIntegerValue(currentKey) && value < minUpper) {
                minUpper = value;
            }
        }
        if (!keyToMinUpper.containsKey(currentKey) || minUpper < keyToMinUpper.get(currentKey)) {
            keyToMinUpper.put(currentKey, minUpper);
        }
    }
    for (int i = 0; i < keys.size(); i++) {
        K key = keys.get(i);
        Integer bound = keyToMinUpper.get(key);
        upperBounds.set(i, bound != null ? bound : Integer.MAX_VALUE);
    }
    return upperBounds;
}

private int toIntegerValue(K key) {
    if (key == null) {
        return 0;
    }
    if (key instanceof Number) {
        return ((Number) key).intValue();
    }
    // Fallback: use hashCode modulo to ensure non-negative small range if needed
    return key.hashCode() & 0x7FFFFFFF;
}

