static String[] toNoNullStringArray(Object[] array){
    if (array == null) {
        return null;
    }

    // First pass: check if there are any nulls
    boolean hasNull = false;
    for (Object element : array) {
        if (element == null) {
            hasNull = true;
            break;
        }
    }

    // If no nulls, return the array cast to String[]
    if (!hasNull) {
        return (String[]) array;
    }

    // Count non-null elements
    int count = 0;
    for (Object element : array) {
        if (element != null) {
            count++;
        }
    }

    // Create new array and copy non-null elements
    String[] result = new String[count];
    int index = 0;
    for (Object element : array) {
        if (element != null) {
            result[index++] = element.toString();
        }
    }

    return result;
}
