public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> allSnapshots = new ArrayList<>();

    if (file == null || !file.exists()) {
        return allSnapshots;
    }

    if (timeRanges == null || timeRanges.isEmpty()) {
        return allSnapshots;
    }

    List<ThreadSnapshot> snapshots = parseFromFile(file);
    if (snapshots == null || snapshots.isEmpty()) {
        return allSnapshots;
    }

    // Filter snapshots based on the provided time ranges
    for (ThreadSnapshot snapshot : snapshots) {
        long snapshotTime = snapshot.getTimestamp();

        for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
            if (timeRange == null) {
                continue;
            }

            long startTime = timeRange.getStartTime();
            long endTime = timeRange.getEndTime();

            if (snapshotTime >= startTime && snapshotTime <= endTime) {
                allSnapshots.add(snapshot);
                break; // Avoid adding duplicates if snapshot falls into multiple ranges
            }
        }
    }

    return allSnapshots;
}
